public anytype getValueOfAttribute(Common _pricingObject)
{
    RefRecId colorId = this.getTableRecord(_pricingObject).Color;
    return EcoResColor::find(colorId).Name;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    QueryBuildDataSource qbdsColor = _qbds.addDataSource(tableNum(EcoResColor));
    qbdsColor.joinMode(JoinMode::InnerJoin);
    qbdsColor.addLink(fieldNum(EcoResProductVariantColor, Color), fieldNum(EcoResColor, RecId));
    qbdsColor.addRange(fieldNum(EcoResColor, Name)).value(queryValue(_value));
}

public void buildEcoResProductVariantQuery(Query _query, anytype _value, QueryBuildDataSource _qbds)
{
    if (_qbds.table() != tableNum(EcoResDistinctProductVariant))
    {
        return;
    }

    QueryBuildDataSource qbdsVariantColor, qbdsColor;
    qbdsVariantColor = _qbds.addDataSource(tableNum(EcoResProductVariantColor));
    qbdsVariantColor.joinMode(JoinMode::ExistsJoin);
    qbdsVariantColor.addLink(fieldNum(EcoResDistinctProductVariant, RecId), fieldNum(EcoResProductVariantColor, DistinctProductVariant));

    qbdsColor = qbdsVariantColor.addDataSource(tableNum(EcoResColor));
    qbdsColor.joinMode(JoinMode::InnerJoin);
    qbdsColor.addLink(fieldNum(EcoResProductVariantColor,Color), fieldNum(EcoResColor, RecId));

    qbdsColor.addRange(fieldNum(EcoResColor, Name)).value(queryValue(_value));
}
